alpha = 8  # faces and labels 1..8; octahedron-face graph is the cube Q3

# Helper: build cube graph edges and opposite pairs for Q3
def cube_edges_and_opposites():
    # vertices labeled 0..7 (3-bit)
    edges = []
    for v in range(8):
        for b in (1, 2, 4):
            u = v ^ b
            if v < u:
                edges.append((v, u))
    mask = 7
    opposites = []
    for v in range(8):
        u = v ^ mask
        if v < u:
            opposites.append((v, u))
    return edges, opposites

edges, opposites = cube_edges_and_opposites()

def count_valid(edge_forb_diffs, opp_forb_diffs):
    # Build symmetric forbidden sets modulo alpha
    def build_forb(diffs):
        s = set()
        for d in diffs:
            d0 = d % alpha
            s.add(d0)
            s.add((-d0) % alpha)
        return s
    edge_forb_mods = build_forb(edge_forb_diffs)
    opp_forb_mods = build_forb(opp_forb_diffs)
    total = math.factorial(alpha)
    cnt = 0
    for perm in itertools.permutations(range(1, alpha + 1)):
        ok = True
        # check edges
        for (u, v) in edges:
            a = perm[u]
            b = perm[v]
            d = (b - a) % alpha
            if d in edge_forb_mods:
                ok = False
                break
        if not ok:
            continue
        # check opposites
        for (u, v) in opposites:
            a = perm[u]
            b = perm[v]
            d = (b - a) % alpha
            if d in opp_forb_mods:
                ok = False
                break
        if ok:
            cnt += 1
    return cnt, total

# Try to sample nontrivial constraints that admit solutions
