return {
    'alpha': alpha,
    'edge_forb_diffs_str': to_str(edge_forb),
    'opp_forb_diffs_str': to_str(opp_forb),
    'edge_forb_diffs': edge_forb,
    'opp_forb_diffs': opp_forb
